import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const manifestPath = path.join(root, 'MANIFEST.sha256');
const checkOnly = process.argv.includes('--check');
const excludedDirectories = new Set([
  '.git',
  'node_modules',
  'dist',
  'target',
  'output',
  '__pycache__',
  // Generated by the extension build; the authored extension lives in
  // extension/ and is what belongs in the source manifest.
  'extension-dist',
]);
const excludedPrefixes = [
  'docs/screenshots/',
  'docs/tests/',
  'src-tauri/resources/bin/',
  // Generated by Tauri during cargo check/build. These schemas are build
  // products, not authored source, and may remain after an interrupted build.
  'src-tauri/gen/',
];
const excludedFiles = new Set([
  'MANIFEST.sha256',
  'package-lock.json',
  'src-tauri/Cargo.lock',
  // Produced by build-store-msix.ps1 from extension/native-host.
  'src-tauri/resources/extension/cacatools-native-host.exe',
  'src-tauri/resources/licenses/ARIA2-COPYING.txt',
  'src-tauri/resources/licenses/ARIA2-OPENSSL-LICENSE.txt',
  'src-tauri/resources/licenses/ARIA2-NOTICE.txt',
  'src-tauri/resources/licenses/FFMPEG-BUILD-README.txt',
  'src-tauri/resources/licenses/FFMPEG-LICENSE.txt',
  'src-tauri/resources/licenses/FFMPEG-NOTICE.txt',
  // Generated into the resource folder immediately before Windows packaging.
  'src-tauri/resources/licenses/THIRD_PARTY_NOTICES.txt',
  'src-tauri/resources/licenses/YT-DLP-NOTICE.txt',
  'src-tauri/resources/licenses/YT-DLP-THIRD-PARTY-LICENSES.txt',
  'desktop.ini',
  'Thumbs.db',
]);

// Files copied beside or into the source tree by browsers, support chats, and
// failed build attempts are not executable source and must not invalidate the
// reproducible source manifest.
const excludedArtifactPatterns = [
  /(^|\/)build-transcript(?:\(\d+\))?\.txt$/i,
  /(^|\/)final-build-transcript\.txt$/i,
  /(^|\/)native-diagnostics(?:\.zip)?$/i,
  /\.zip$/i,
  /\.zip\.sha256$/i,
  /\.log$/i,
  /\.tmp$/i,
  /\.partial$/i,
];

function normalize(relative) {
  return relative.replaceAll(path.sep, '/');
}

function shouldInclude(relative, entry) {
  const normalized = normalize(relative);
  if (excludedFiles.has(normalized) || excludedFiles.has(entry.name)) return false;
  if (excludedPrefixes.some((prefix) => normalized.startsWith(prefix))) return false;
  if (excludedArtifactPatterns.some((pattern) => pattern.test(normalized))) return false;
  if (entry.isDirectory()) {
    return !excludedDirectories.has(entry.name) && !/^target(?:-|$)/i.test(entry.name);
  }
  return !entry.isSymbolicLink();
}

function walk(directory, relative = '') {
  const files = [];
  const entries = fs.readdirSync(directory, { withFileTypes: true }).sort((a, b) =>
    a.name.localeCompare(b.name),
  );
  for (const entry of entries) {
    const nextRelative = relative ? path.join(relative, entry.name) : entry.name;
    if (!shouldInclude(nextRelative, entry)) continue;
    const absolute = path.join(directory, entry.name);
    if (entry.isDirectory()) files.push(...walk(absolute, nextRelative));
    else if (entry.isFile()) files.push(normalize(nextRelative));
  }
  return files;
}

// Git stores text files with canonical LF bytes, while Windows checkouts may
// materialize the same files as CRLF according to .gitattributes.  Hashing
// the raw working-tree bytes made the source gate depend on core.autocrlf and
// caused clean CI checkouts to disagree with manifests generated on Windows.
// Canonicalize authored text before hashing so the manifest is reproducible on
// every platform while binary assets remain byte-for-byte verified.
const textExtensions = new Set([
  '.bat', '.cmd', '.css', '.html', '.js', '.json', '.md', '.mjs', '.ps1',
  '.lock', '.py', '.rs', '.svg', '.toml', '.txt', '.xml', '.yml', '.yaml',
]);
const textBasenames = new Set(['.gitattributes', '.gitignore', '.npmrc', 'CODEOWNERS']);

function canonicalBytes(relative, bytes) {
  const basename = path.basename(relative);
  const extension = path.extname(relative).toLowerCase();
  if (!textExtensions.has(extension) && !textBasenames.has(basename)) return bytes;
  return Buffer.from(bytes.toString('utf8').replace(/\r\n?/g, '\n'), 'utf8');
}

function sha256(relative) {
  const bytes = fs.readFileSync(path.join(root, relative));
  return crypto.createHash('sha256').update(canonicalBytes(relative, bytes)).digest('hex');
}

function parseManifest(text) {
  const entries = new Map();
  for (const rawLine of text.replaceAll('\r\n', '\n').split('\n')) {
    const line = rawLine.trimEnd();
    if (!line) continue;
    const match = /^([0-9a-fA-F]{64})  (.+)$/.exec(line);
    if (!match) throw new Error(`Línea inválida en MANIFEST.sha256: ${line}`);
    entries.set(match[2], match[1].toLowerCase());
  }
  return entries;
}

const currentEntries = new Map(walk(root).map((relative) => [relative, sha256(relative)]));
const lines = [...currentEntries.entries()].map(([relative, hash]) => `${hash}  ${relative}`);
const output = `${lines.join('\n')}\n`;

if (checkOnly) {
  if (!fs.existsSync(manifestPath)) {
    console.error('FALTA: MANIFEST.sha256');
    process.exit(1);
  }

  let expectedEntries;
  try {
    expectedEntries = parseManifest(fs.readFileSync(manifestPath, 'utf8'));
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  }

  const missing = [];
  const changed = [];
  const unexpected = [];

  for (const [relative, expectedHash] of expectedEntries) {
    const actualHash = currentEntries.get(relative);
    if (!actualHash) missing.push(relative);
    else if (actualHash !== expectedHash) changed.push(relative);
  }
  for (const relative of currentEntries.keys()) {
    if (!expectedEntries.has(relative)) unexpected.push(relative);
  }

  if (missing.length || changed.length || unexpected.length) {
    console.error('MANIFEST.sha256 no coincide con el código fuente actual.');
    const show = (label, values) => {
      if (!values.length) return;
      console.error(`${label} (${values.length}):`);
      for (const value of values.slice(0, 25)) console.error(`  - ${value}`);
      if (values.length > 25) console.error(`  ... y ${values.length - 25} más`);
    };
    show('Faltan', missing);
    show('Modificados', changed);
    show('No registrados', unexpected);
    console.error('No regeneres el manifiesto salvo que hayas aplicado un hotfix oficial o modificado el código conscientemente.');
    process.exit(1);
  }

  console.log(`OK: manifiesto fuente verificado (${currentEntries.size} archivos).`);
} else {
  fs.writeFileSync(manifestPath, output);
  console.log(`OK: MANIFEST.sha256 generado (${currentEntries.size} archivos).`);
}
